import { describe, it, expect } from 'vitest';
import { open, get as zarrGet } from 'zarrita';
import { FileSystemStore } from '@zarrita/storage';
import { fileURLToPath } from 'url';
import { join, dirname } from 'path';
import { readFileSync } from 'fs';
import { ImageSchema } from 'zod-ome-ngff/0.5';
import { OmeTiffAsOmeZarrStore } from '../src/OmeTiffAsOmeZarrStore.js';
import { TiffAsOmeZarrStore } from '../src/TiffAsOmeZarrStore.js';

// Fixtures generated by fixtures/create_edge_case_fixtures.py.
const __dirname = dirname(fileURLToPath(import.meta.url));
const EDGE_CASES = join(__dirname, '..', 'fixtures', 'edge_cases');
const refStore = new FileSystemStore(join(EDGE_CASES, 'reference.zarr'));

async function openPlain(name: string) {
  return TiffAsOmeZarrStore.fromStore(new FileSystemStore(join(EDGE_CASES, `${name}.tif`)));
}

async function openOme(name: string) {
  return OmeTiffAsOmeZarrStore.fromStore(new FileSystemStore(join(EDGE_CASES, `${name}.ome.tif`)));
}

async function rootAttrs(store: TiffAsOmeZarrStore | OmeTiffAsOmeZarrStore) {
  const group = await open(store, { kind: 'group' });
  const attrs = group.attrs as any;
  expect(() => ImageSchema.parse(attrs)).not.toThrow();
  return attrs.ome;
}

/** Every level of the virtual store matches the reference arrays exactly. */
async function expectMatchesReference(
  store: TiffAsOmeZarrStore | OmeTiffAsOmeZarrStore,
  name: string,
  numLevels = 1,
) {
  const ome = await rootAttrs(store);
  expect(ome.multiscales[0].datasets.length).toBe(numLevels);
  const group = await open(store, { kind: 'group' });
  const refGroup = await open(refStore, { kind: 'group' });
  for (let level = 0; level < numLevels; level++) {
    const arr = await open(group.resolve(String(level)), { kind: 'array' });
    const ref = await open(refGroup.resolve(`${name}/${level}`), { kind: 'array' });
    expect(arr.shape).toEqual(ref.shape);
    expect(arr.dtype).toBe(ref.dtype);
    const [actual, expected] = await Promise.all([zarrGet(arr), zarrGet(ref)]);
    expect(actual.data).toEqual(expected.data);
  }
}

describe('TiffAsOmeZarrStore – stripped layouts', () => {
  for (const [name, bytesPerSample] of [['strip_u16_none', 2], ['strip_u8_lzw', 1], ['strip_i16_be_zlib_pred2', 2]] as const) {
    it(`${name}: chunk height is RowsPerStrip and the short last strip is padded`, async () => {
      const store = await openPlain(name);
      const arr = await open((await open(store, { kind: 'group' })).resolve('0'), { kind: 'array' });
      expect(arr.chunks).toEqual([16, 90]);
      // 100 rows / 16 rows per strip → 7 strips; the last holds 4 rows but
      // must be returned as a full 16-row chunk.
      const lastChunk = await store.get('/0/c/6/0');
      expect(lastChunk?.length).toBe(16 * 90 * bytesPerSample);
      await expectMatchesReference(store, name);
    });
  }
});

describe('TiffAsOmeZarrStore – predictors and codecs', () => {
  for (const name of [
    'tile_u2_le_pred2',
    'tile_u2_be_pred2',
    'tile_i4_le_pred2',
    'tile_f4_le_pred3',
    'tile_f8_be_pred3',
    'tile_u16_zstd',
  ]) {
    it(`${name}: pixel values match reference`, async () => {
      await expectMatchesReference(await openPlain(name), name);
    });
  }
});

describe('TiffAsOmeZarrStore – multi-sample (RGB) layouts', () => {
  it('chunky tiled RGB is exposed as c, y, x with all samples in one chunk', async () => {
    const store = await openPlain('rgb_contig_tiled_pred2');
    const ome = await rootAttrs(store);
    expect(ome.multiscales[0].axes).toEqual([
      { name: 'c', type: 'channel' },
      { name: 'y', type: 'space' },
      { name: 'x', type: 'space' },
    ]);
    const arr = await open((await open(store, { kind: 'group' })).resolve('0'), { kind: 'array' });
    expect(arr.chunks).toEqual([3, 32, 32]);
    await expectMatchesReference(store, 'rgb_contig_tiled_pred2');
  });

  it('chunky stripped RGB pixel values match reference', async () => {
    await expectMatchesReference(await openPlain('rgb_contig_strip'), 'rgb_contig_strip');
  });

  it('planar-separate tiled RGB reads sample planes from one IFD', async () => {
    const store = await openPlain('rgb_separate_tiled');
    const arr = await open((await open(store, { kind: 'group' })).resolve('0'), { kind: 'array' });
    expect(arr.chunks).toEqual([1, 32, 32]);
    await expectMatchesReference(store, 'rgb_separate_tiled');
  });

  it('planar-separate stripped big-endian RGB pixel values match reference', async () => {
    await expectMatchesReference(await openPlain('rgb_separate_strip_be'), 'rgb_separate_strip_be');
  });

  it('rejects out-of-range channel chunks', async () => {
    const store = await openPlain('rgb_separate_tiled');
    expect(await store.get('/0/c/3/0/0')).toBeUndefined();
    expect(await store.get('/0/c/0/4/0')).toBeUndefined();
    expect(await store.get('/0/c/0/0')).toBeUndefined();
  });
});

describe('TiffAsOmeZarrStore – pyramid with non-square tiles', () => {
  it('exposes every SubIFD level with IFD-derived shapes and scales', async () => {
    const store = await openPlain('pyramid_plain');
    const ome = await rootAttrs(store);
    expect(ome.multiscales[0].datasets.map((d: any) => d.coordinateTransformations[0].scale)).toEqual([
      [1, 1],
      [2, 2],
      [4, 4],
    ]);
    const group = await open(store, { kind: 'group' });
    const arr2 = await open(group.resolve('2'), { kind: 'array' });
    // 100×90 → 50×45 → 25×23 (ceil-halving), not 25×22.
    expect(arr2.shape).toEqual([25, 23]);
    expect(arr2.chunks).toEqual([32, 48]);
    await expectMatchesReference(store, 'pyramid_plain', 3);
  });
});

describe('OmeTiffAsOmeZarrStore – Z-stack with physical sizes', () => {
  it('exposes c, z, y, x axes with converted units', async () => {
    const ome = await rootAttrs(await openOme('ome_zstack'));
    expect(ome.multiscales[0].axes).toEqual([
      { name: 'c', type: 'channel' },
      { name: 'z', type: 'space', unit: 'nanometer' },
      { name: 'y', type: 'space', unit: 'micrometer' },
      { name: 'x', type: 'space', unit: 'micrometer' },
    ]);
  });

  it('scales include PhysicalSizeZ and per-level factors', async () => {
    const ome = await rootAttrs(await openOme('ome_zstack'));
    expect(ome.multiscales[0].datasets.map((d: any) => d.coordinateTransformations[0].scale)).toEqual([
      [1, 2, 0.25, 0.5],
      [1, 2, 0.5, 1],
      [1, 2, 1, 2],
    ]);
  });

  it('omero window spans the uint16 range', async () => {
    const ome = await rootAttrs(await openOme('ome_zstack'));
    expect(ome.omero.channels.map((c: any) => c.label)).toEqual(['A', 'B']);
    expect(ome.omero.channels[0].window).toEqual({ min: 0, max: 65535, start: 0, end: 65535 });
  });

  it('non-square tiles are used as the chunk shape', async () => {
    const store = await openOme('ome_zstack');
    const arr = await open((await open(store, { kind: 'group' })).resolve('0'), { kind: 'array' });
    expect(arr.chunks).toEqual([1, 1, 32, 48]);
  });

  it('pixel values match reference at every level', async () => {
    await expectMatchesReference(await openOme('ome_zstack'), 'ome_zstack', 3);
  });
});

describe('OmeTiffAsOmeZarrStore – stripped', () => {
  it('uses strips as chunks and matches reference', async () => {
    const store = await openOme('ome_stripped');
    const ome = await rootAttrs(store);
    expect(ome.omero.channels[0].window).toEqual({ min: 0, max: 255, start: 0, end: 255 });
    const arr = await open((await open(store, { kind: 'group' })).resolve('0'), { kind: 'array' });
    expect(arr.chunks).toEqual([1, 16, 90]);
    await expectMatchesReference(store, 'ome_stripped');
  });
});

describe('chunk encoding: passthrough vs decode in store', () => {
  async function arrayCodecs(store: TiffAsOmeZarrStore | OmeTiffAsOmeZarrStore, level = 0) {
    return JSON.parse(new TextDecoder().decode(await store.get(`/${level}/zarr.json`))).codecs;
  }

  /** Passthrough chunks are byte-for-byte slices of the TIFF file. */
  function expectSliceOfFile(chunk: Uint8Array | undefined, file: string) {
    expect(chunk).toBeDefined();
    expect(readFileSync(join(EDGE_CASES, file)).indexOf(Buffer.from(chunk!))).toBeGreaterThan(0);
  }

  for (const [name, codecs] of [
    ['tile_u16_zstd', [{ name: 'bytes', configuration: { endian: 'little' } }, { name: 'zstd', configuration: { level: 0, checksum: false } }]],
    ['strip_u16_zlib_even', [{ name: 'bytes', configuration: { endian: 'little' } }, { name: 'zlib', configuration: { level: 1 } }]],
    ['rgb_separate_strip_be', [{ name: 'bytes', configuration: { endian: 'big' } }]],
  ] as const) {
    it(`${name}: passes raw segment bytes through`, async () => {
      const store = await openPlain(name);
      expect(await arrayCodecs(store)).toEqual(codecs);
      const firstChunk = name === 'rgb_separate_strip_be' ? '/0/c/1/0/0' : '/0/c/0/0';
      expectSliceOfFile(await store.get(firstChunk), `${name}.tif`);
      await expectMatchesReference(store, name);
    });
  }

  it('uncompressed short last strip is padded in passthrough mode', async () => {
    const store = await openPlain('strip_u16_none');
    expect(await arrayCodecs(store)).toEqual([{ name: 'bytes', configuration: { endian: 'little' } }]);
    expectSliceOfFile(await store.get('/0/c/0/0'), 'strip_u16_none.tif');
    expect((await store.get('/0/c/6/0'))?.length).toBe(16 * 90 * 2);
  });

  it('OME-TIFF zlib tiles pass through at every level', async () => {
    const file = join(__dirname, '..', 'fixtures', '9836842.v0_3.ome.tif');
    const store = await OmeTiffAsOmeZarrStore.fromStore(new FileSystemStore(file));
    for (let level = 0; level < 6; level++) {
      expect(await arrayCodecs(store, level)).toEqual([
        { name: 'bytes', configuration: { endian: 'little' } },
        { name: 'zlib', configuration: { level: 1 } },
      ]);
    }
    const chunk = await store.get('/5/c/2/0/0');
    expect(readFileSync(file).indexOf(Buffer.from(chunk!))).toBeGreaterThan(0);
  });

  it('OME-TIFF with a predictor is decoded in the store', async () => {
    const zstack = await openOme('ome_zstack');
    // ome_zstack uses predictor 2, so it is decoded in the store.
    expect(await arrayCodecs(zstack, 2)).toEqual([{ name: 'bytes', configuration: { endian: 'little' } }]);
    expect((await zstack.get('/2/c/1/2/0/0'))?.length).toBe(32 * 48 * 2);
  });

  for (const name of ['strip_u16_zlib', 'strip_u8_lzw', 'tile_u16_zstd_pred2', 'tile_u2_be_pred2', 'tile_f4_le_pred3', 'rgb_contig_tiled_pred2', 'rgb_contig_strip']) {
    it(`${name}: is decoded in the store`, async () => {
      const store = await openPlain(name);
      expect(await arrayCodecs(store)).toEqual([{ name: 'bytes', configuration: { endian: 'little' } }]);
      await expectMatchesReference(store, name);
    });
  }
});
